// ⚠️ ВОЙДИ В n8n → Credentials → Telegram Bot Token → скопируй токен сюда:
const BOT_TOKEN = '8385465224:AAE7k1qxCjJ8SKG2BXleFPqaJIUPWJRF7NQ';

const message = $('Telegram Trigger').first().json.message;
const fileId = message.voice.file_id;

// 1. Получаем путь к файлу
const fileInfo = await this.helpers.httpRequest({
  method: 'GET',
  url: `https://api.telegram.org/bot${BOT_TOKEN}/getFile?file_id=${fileId}`,
  json: true,
});
if (!fileInfo.ok) throw new Error('getFile failed: ' + JSON.stringify(fileInfo));

const filePath = fileInfo.result.file_path;

// 2. Скачиваем файл как бинарные данные
const fileBuffer = await this.helpers.request({
  method: 'GET',
  url: `https://api.telegram.org/file/bot${BOT_TOKEN}/${filePath}`,
  encoding: null,
});

const binaryData = await this.helpers.prepareBinaryData(
  fileBuffer,
  'voice.oga',
  'audio/ogg'
);

return [{
  json: { chatId: message.chat.id },
  binary: { voiceFile: binaryData }
}];
